import {toast} from "react-toastify";
import {getApiErrorMessage} from "../../api/errors";
import React, {useState} from "react";
import styledCom from "styled-components";
import CoreTextField from "../../ui/textFields/coreTextField";
import {Button, Dialog, DialogActions, DialogTitle} from "@mui/material";
import {ICategory} from "../../models/category";
import {useTranslation} from "../../i18n";

interface IProps {
    open: boolean;
    setOpen: any;
    categoryToEdit: ICategory | undefined;
    setCategoryToEdit: any;
    editCategory: any;
}

const ModalForm = styledCom.form({
    display: "grid",
    gap: "12px",
    padding: "0 24px 16px",
});

const EditCategoryModal = ({open, categoryToEdit, setCategoryToEdit, setOpen, editCategory}: IProps) => {
    const {t} = useTranslation();
    const [isSaving, setSaving] = useState(false);

    const handleSubmit = async (event: any) => {
        event.preventDefault();
        if (!categoryToEdit || isSaving) return;
        setSaving(true);
        try {
            await editCategory({
                categoryId: categoryToEdit.id,
                category: {name: categoryToEdit.name},
            }).unwrap();
            toast.success(t("Категория сохранена."));
            setCategoryToEdit(undefined);
            setOpen(false);
        } catch (failure) {
            toast.error(getApiErrorMessage(failure, t("Не удалось сохранить запись.")));
        } finally {
            setSaving(false);
        }
    };

    if (!categoryToEdit || !open) {
        return null;
    }

    return (
        <Dialog
            fullWidth
            open={open}
            onClose={() => {if (!isSaving) setOpen(false);}}
        >
            <DialogTitle>{t("Редактирование категории")}</DialogTitle>
            <ModalForm onSubmit={(e: React.FormEvent<HTMLFormElement>) => handleSubmit(e)}>
                <CoreTextField
                    required
                    label={t("Название категории")}
                    value={categoryToEdit.name}
                    onChange={(event: any) => {
                        setCategoryToEdit({...categoryToEdit, name: event.target.value});
                    }}
                />
                <DialogActions sx={{padding: 0}}>
                    <Button disabled={isSaving} onClick={() => setOpen(false)}>{t("Отмена")}</Button>
                    <Button type="submit" disabled={isSaving}>{t("Сохранить")}</Button>
                </DialogActions>
            </ModalForm>
        </Dialog>
    );
};

export default EditCategoryModal;
