import {GridActionsCellItem, GridColDef, GridRowId, GridRowParams} from "@mui/x-data-grid";
import EditTwoToneIcon from "@mui/icons-material/EditTwoTone";
import DeleteTwoToneIcon from "@mui/icons-material/DeleteTwoTone";
import React from "react";
import {ICategory} from "../../models/category";
import {Translate} from "../../i18n";

const categoryColumns: (
    handleSetCategoryToDelete: (id: GridRowId) => void,
    handleSetCategoryToEdit: (category: ICategory) => void,
    t: Translate,
) => GridColDef[] = (handleSetCategoryToDelete, handleSetCategoryToEdit, t) => [
    {
        field: "name",
        headerName: t("Название"),
        minWidth: 240,
        flex: 1,
    },
    {
        field: "Edit",
        headerName: t("Правка"),
        type: "actions",
        width: 92,
        getActions: (params: GridRowParams) => [
            <GridActionsCellItem
                icon={<EditTwoToneIcon/>}
                label={t("Редактировать")}
                onClick={() => handleSetCategoryToEdit(params.row)}
            />,
        ],
    },
    {
        field: "Delete",
        headerName: t("Удалить"),
        type: "actions",
        width: 92,
        getActions: (params: GridRowParams) => [
            <GridActionsCellItem
                icon={<DeleteTwoToneIcon/>}
                label={t("Удалить")}
                onClick={() => handleSetCategoryToDelete(params.id)}
            />,
        ],
    },
];

export default categoryColumns;
