import {toast} from "react-toastify";
import {getApiErrorMessage} from "../../api/errors";
import QueryError from "../shared/QueryError";
import React, {useState} from "react";
import {
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogContentText,
    DialogTitle,
    Link,
} from "@mui/material";
import AccountTreeOutlinedIcon from "@mui/icons-material/AccountTreeOutlined";
import HubOutlinedIcon from "@mui/icons-material/HubOutlined";
import Loader from "../../ui/loader/loader";
import CoreButton from "../../ui/buttons/coreButton";
import categoryColumns from "./categoryColums";
import {
    MainDiv,
    PageHeader,
    PageSubtitle,
    PageTitle,
    PageTitleGroup,
    StyledDataGrid,
    Surface,
    Toolbar,
    ToolbarActions,
} from "../../ui/commonStyled/commonStyled";
import {Link as RouterLink} from "react-router-dom";
import EditCategoryModal from "./EditCategoryModal";
import {CategoryType, ICategory} from "../../models/category";
import {
    useDeleteCategoryMutation,
    useEditCategoryMutation,
    useGetCategoriesQuery,
} from "./categoriesApi";
import {useTranslation} from "../../i18n";

interface CategoriesManagementProps {
    categoryType?: CategoryType;
    basePath?: string;
}

const CategoriesManagement = ({
                                  categoryType = CategoryType.Product,
                                  basePath = "/productCategories",
                              }: CategoriesManagementProps) => {
    const {data: categories = [], isLoading, isError, error, refetch} = useGetCategoriesQuery({type: categoryType});
    const [deleteCategory, {isLoading: isDeleting}] = useDeleteCategoryMutation({});
    const [editCategory] = useEditCategoryMutation({});
    const {t} = useTranslation();
    const isServiceCategory = categoryType === CategoryType.Service;

    const [categoryToDelete, setCategoryToDelete] = useState<number>(-1);
    const [categoryToEdit, setCategoryToEdit] = useState<ICategory | undefined>();
    const [deleteWindowOpen, setDeleteWindowOpen] = useState(false);
    const [editWindowOpen, setEditWindowOpen] = useState(false);

    const handleSetCategoryToDelete = (id: any) => {
        setDeleteWindowOpen(true);
        setCategoryToDelete(id);
    };

    const handleSetCategoryToEdit = (category: ICategory) => {
        setCategoryToEdit(category);
        setEditWindowOpen(true);
    };

    const deleteCategoryHandler = async () => {
        if (isDeleting || categoryToDelete < 0) return;
        try {
            await deleteCategory(categoryToDelete).unwrap();
            toast.success(t("Категория удалена."));
            setCategoryToDelete(-1);
            setDeleteWindowOpen(false);
        } catch (failure) {
            toast.error(getApiErrorMessage(failure, t("Не удалось удалить запись.")));
        }
    };

    if (isLoading) {
        return <Loader/>;
    }

    if (isError) return <MainDiv><QueryError error={error} onRetry={refetch}/></MainDiv>;

    return (
        <MainDiv>
            <Dialog open={deleteWindowOpen} onClose={() => {if (!isDeleting) setDeleteWindowOpen(false);}}>
                <DialogTitle>{t("Confirm category deletion")}</DialogTitle>
                <DialogContent>
                    <DialogContentText>
                        {t("Deleting a category can rebuild the hierarchy. Categories with catalog items cannot be deleted.")}
                    </DialogContentText>
                </DialogContent>
                <DialogActions>
                    <Button disabled={isDeleting} onClick={() => setDeleteWindowOpen(false)} autoFocus>{t("Cancel")}</Button>
                    <Button color="error" disabled={isDeleting} onClick={deleteCategoryHandler}>{t("Delete")}</Button>
                </DialogActions>
            </Dialog>

            <EditCategoryModal
                open={editWindowOpen}
                setOpen={setEditWindowOpen}
                categoryToEdit={categoryToEdit}
                setCategoryToEdit={setCategoryToEdit}
                editCategory={editCategory}
            />

            <PageHeader>
                <PageTitleGroup>
                    <PageTitle>{isServiceCategory ? t("Service categories") : t("Product categories")}</PageTitle>
                    <PageSubtitle>
                        {isServiceCategory
                            ? t("Structure service categories separately from product catalog data.")
                            : t("Structure product categories separately from service catalog data.")}
                    </PageSubtitle>
                </PageTitleGroup>
            </PageHeader>

            <Surface>
                <Toolbar>
                    <ToolbarActions>
                        <Link
                            component={RouterLink}
                            style={{textDecoration: "none"}}
                            to={`${basePath}/hierarchy`}
                        >
                            <CoreButton
                                muiType="info"
                                text={t("Manage hierarchy")}
                                leftIcon={<AccountTreeOutlinedIcon/>}
                            />
                        </Link>
                        <Link
                            component={RouterLink}
                            style={{textDecoration: "none"}}
                            to={`${basePath}/categoriesGraphTree`}
                        >
                            <CoreButton
                                text={t("Category map")}
                                leftIcon={<HubOutlinedIcon/>}
                            />
                        </Link>
                    </ToolbarActions>
                </Toolbar>

                <StyledDataGrid
                    pagination
                    autoHeight
                    rows={categories}
                    columns={categoryColumns(handleSetCategoryToDelete, handleSetCategoryToEdit, t)}
                    pageSizeOptions={[25, 50, 100]}
                    disableRowSelectionOnClick
                />
            </Surface>
        </MainDiv>
    );
};

export default CategoriesManagement;
